Templates.Starter:
{{/* @dot github.com/donseba/go-webthings/modules/lists.ListView */}}
<main id="content">
    <h1>{{.Title}}</h1>

    {{range .Entries}}
        <section id="{{.ID}}">
            {{with .ImageURL}}<img src="{{image . "400x300 crop"}}" alt="">{{end}}
            <h2>{{.Title}}</h2>
            {{.Body}}
            {{with .Link}}<p><a href="{{.}}">Read more</a></p>{{end}}
        </section>
    {{else}}
        <p>Nothing here yet.</p>
    {{end}}
</main>

Types.Decl:
type APIEntry struct {
	ID       string     `json:"id"`
	Title    string     `json:"title"`
	BodyHTML string     `json:"body_html"`
	Image    *api.Image `json:"image"`
	// Link is the entry's link as a visitor follows it from the list's
	// page: a path of the site made absolute, an anchor on the list's
	// page, other addresses (https:, mailto:, tel:) as they are; null
	// without a link.
	Link *string `json:"link"`
	// URL is the entry on the list's page (#<id>), null while the list is
	// on no page; APIURL the entry in the API.
	URL       *string   `json:"url"`
	APIURL    string    `json:"api_url"`
	UpdatedAt time.Time `json:"updated_at"`
}

type Entry struct {
	ID    string
	Title string
	Body  template.HTML
	// ImageURL is the entry's image as pages show it, at most media.ImageWidth
	// wide (see frontend.Frontend.Image); ImageSrcset lists smaller
	// copies for a srcset attribute, ImageWidth and ImageHeight are the
	// size of ImageURL and ImageOriginalURL is the uploaded file, for
	// downloads. All are empty when the entry has no image.
	ImageURL         string
	ImageSrcset      string
	ImageOriginalURL string
	ImageWidth       int
	ImageHeight      int
	// Link is empty when not set. It is a template.URL because the store only
	// accepts paths, anchors and http(s), mailto: and tel: addresses, so
	// templates can use it in href without html/template replacing tel:
	// links with #ZgotmplZ.
	Link template.URL
}

type Fields struct {
	Image string `db:"image_id,null"`
	Link  string `db:"link_url"`
}

type ListView struct {
	// Key is the list's instance key, for example "faq", so one template can
	// show several lists differently.
	Key string
	// Title is the title of the page the list is mounted on.
	Title   string
	Entries []Entry
}

type Service struct {
	// contains unexported fields
}

type Text struct {
	Title string `db:"title"`
	Body  string `db:"body"`
}
